INSERT OR REPLACE INTO "DataQuest" ("ID","Name","StartType","StartName","StartRegionID","AcceptText","Description","SourceName","SourceText","StepType","StepText","StepItemTemplates","AdvanceText","TargetName","TargetText","CollectItemTemplate","MaxCount","MinLevel","MaxLevel","RewardMoney","RewardXP","RewardCLXP","RewardRP","RewardBP","OptionalRewardItemTemplates","FinalRewardItemTemplates","FinishText","QuestDependency","AllowedClasses","ClassType","LastTimeRowUpdated") VALUES (20225,'The Forest Plot',0,'Rob Ria',1,'Snowdonia','The Mist Hunters need a scout''s bow: kill a gytrash in the Pennines and an Arawnite shamaness in [Snowdonia].','','Kill a gytrash in the Pennine Mountains (midnight to 6 A.M.).||','0|0|5','Kill a gytrash in the Pennine Mountains (midnight to 6 A.M.).|Kill an Arawnite shamaness outside Snowdonia Fortress, at the first camp fire on the right.|Return to Rob Ria for your reward.','||','||','gytrash;1|Arawnite shamaness;1|Rob Ria;1','||','||',1,40,50,'0|0|0','0|0|64500000',NULL,NULL,NULL,NULL,'cq_alb_bow_of_the_forest_lord','','','3','DOL.GS.Quests.ClassicQuestStep','2026-10-08 06:15:00');
