INSERT OR REPLACE INTO "DataQuest" ("ID","Name","StartType","StartName","StartRegionID","AcceptText","Description","SourceName","SourceText","StepType","StepText","StepItemTemplates","AdvanceText","TargetName","TargetText","CollectItemTemplate","MaxCount","MinLevel","MaxLevel","RewardMoney","RewardXP","RewardCLXP","RewardRP","RewardBP","OptionalRewardItemTemplates","FinalRewardItemTemplates","FinishText","QuestDependency","AllowedClasses","ClassType","LastTimeRowUpdated") VALUES (20303,'Clik''s Raids',0,'Caitriona',200,'snitched','A thieving water beetle named Clik [snitched] my jewels. Help me get them back.','','Kill water beetles up the coast to recover the stolen necklace.||||','0|0|0|0|5','Kill water beetles up the coast to recover the stolen necklace.|And the earring.|And the ring.|Kill Clik in the small bay just southeast of Mag Mell (he calls for help).|Return all four items to Caitriona in Ardagh.','cq_stolen_necklace;40|cq_stolen_earring;40|cq_stolen_ring;40|cq_clik_s_carapace|','||||','water beetle;200|water beetle;200|water beetle;200|Clik;200|Caitriona;200','||||','||||',1,9,14,'0|0|0|0|0','0|0|0|0|17250',NULL,NULL,NULL,NULL,'cq_hib_clik_s_chitin','','','','DOL.GS.Quests.ClassicQuestStep','2026-10-08 06:15:00');
INSERT OR REPLACE INTO "DataQuest" ("ID","Name","StartType","StartName","StartRegionID","AcceptText","Description","SourceName","SourceText","StepType","StepText","StepItemTemplates","AdvanceText","TargetName","TargetText","CollectItemTemplate","MaxCount","MinLevel","MaxLevel","RewardMoney","RewardXP","RewardCLXP","RewardRP","RewardBP","OptionalRewardItemTemplates","FinalRewardItemTemplates","FinishText","QuestDependency","AllowedClasses","ClassType","LastTimeRowUpdated") VALUES (20304,'Rhian''s Dyes',0,'Rhian',200,'components','I am running low on dyes and need [components].','','Get a badger scent gland along the road south from Mag Mell.|||','0|0|0|5','Get a badger scent gland along the road south from Mag Mell.|Get hair from a wild lucradan.|Get the third component from a large eirebug.|Return to Rhian in Tir na mBeo.','cq_badger_scent_gland;50|cq_wild_lucradan_hair;50|cq_large_eirebug_shell;50|','|||','badger;200|wild lucradan;200|large eirebug;200|Rhian;200','|||','|||',1,11,50,'0|0|0|0','0|0|0|31920',NULL,NULL,NULL,NULL,'','','','','DOL.GS.Quests.ClassicQuestStep','2026-10-08 06:15:00');
INSERT OR REPLACE INTO "DataQuest" ("ID","Name","StartType","StartName","StartRegionID","AcceptText","Description","SourceName","SourceText","StepType","StepText","StepItemTemplates","AdvanceText","TargetName","TargetText","CollectItemTemplate","MaxCount","MinLevel","MaxLevel","RewardMoney","RewardXP","RewardCLXP","RewardRP","RewardBP","OptionalRewardItemTemplates","FinalRewardItemTemplates","FinishText","QuestDependency","AllowedClasses","ClassType","LastTimeRowUpdated") VALUES (20305,'The Hunt for Bristle',0,'Eruven',200,'Bristle','Talk to Reidie in Tir na mBeo about [Bristle].','','Talk to Reidie in Tir na mBeo about Bristle. (whisper: Bristle)|||','6|0|2|3','Talk to Reidie in Tir na mBeo about Bristle. (whisper: Bristle)|Find the badger Bristle on the hill west (southwest) of Tir na mBeo and take his head.|Give Bristle''s head to Reidie.|Return to Eruven in Basar and give him the sealed bag.','||cq_bristle_s_head|cq_sealed_bag','Bristle|||','Reidie;200|Bristle;200|Reidie;200|Eruven;200','|||','||cq_bristle_s_head|cq_sealed_bag',1,13,50,'0|0|0|0','0|0|0|67200',NULL,NULL,NULL,NULL,'cq_hib_bristle_s_fang','','Little Wind|Fagan''s Wand','','DOL.GS.Quests.ClassicQuestStep','2026-10-08 06:15:00');
