INSERT OR REPLACE INTO "DataQuest" ("ID","Name","StartType","StartName","StartRegionID","AcceptText","Description","SourceName","SourceText","StepType","StepText","StepItemTemplates","AdvanceText","TargetName","TargetText","CollectItemTemplate","MaxCount","MinLevel","MaxLevel","RewardMoney","RewardXP","RewardCLXP","RewardRP","RewardBP","OptionalRewardItemTemplates","FinalRewardItemTemplates","FinishText","QuestDependency","AllowedClasses","ClassType","LastTimeRowUpdated") VALUES (20385,'Balle''s Potion',0,'Balle',100,'ingredients','Sub-quest of Dark Places of the Soul: gather the [ingredients] for my brew.','','Find the green orms in Skona Ravine and kill one for its bile.|||','0|0|0|5','Find the green orms in Skona Ravine and kill one for its bile.|Find the forest vipers in Vanern Swamp and kill one for venom.|Find the large enslaved orms and kill one for a teardrop.|Give Balle the list, the bile, the venom and the teardrop, in that order.','cq_green_orm_bile;50|cq_forest_viper_venom;50|cq_orm_teardrop;50|','|||','green orm;100|forest viper;100|large enslaved orm;100|Balle;100','|||','|||',1,49,50,'0|0|0|50000','0|0|0|41000000',NULL,NULL,NULL,NULL,'cq_poisonous_brew','','','','DOL.GS.Quests.ClassicQuestStep','2026-10-08 06:15:00');
INSERT OR REPLACE INTO "DataQuest" ("ID","Name","StartType","StartName","StartRegionID","AcceptText","Description","SourceName","SourceText","StepType","StepText","StepItemTemplates","AdvanceText","TargetName","TargetText","CollectItemTemplate","MaxCount","MinLevel","MaxLevel","RewardMoney","RewardXP","RewardCLXP","RewardRP","RewardBP","OptionalRewardItemTemplates","FinalRewardItemTemplates","FinishText","QuestDependency","AllowedClasses","ClassType","LastTimeRowUpdated") VALUES (20386,'Strange Powers',0,'Yver Tiu',100,'Sub-quest','[Sub-quest] of Dark Places of the Soul.','','Find Goi Halfdan upstairs in the house behind the stone wall in Mularn and hand her the sack.|||||','2|4|0|2|2|3','Find Goi Halfdan upstairs in the house behind the stone wall in Mularn and hand her the sack.|Speak with Garon in the first house southwest of the Audliten drop-off.|Seek out Eresidae on a ridge southeast of Dun Crauchon in Emain Macha.|Hand Garon Eresidae''s carcass.|Give Goi Goran''s antidote.|Hand Yver Tiu the enchanter antidote.','cq_yver_s_sack|||cq_eresidae_s_carcass|cq_goran_s_antidote|cq_enchanter_antidote','|||||','Goi Halfdan;100|Garon;100|Eresidae;200|Garon;100|Goi Halfdan;100|Yver Tiu;100','|||||','cq_yver_s_sack|||cq_eresidae_s_carcass|cq_goran_s_antidote|cq_enchanter_antidote',1,49,50,'0|0|0|0|0|50000','0|0|0|0|0|784000000',NULL,NULL,NULL,NULL,'cq_mid_scaffold_web_cloak','','','','DOL.GS.Quests.ClassicQuestStep','2026-10-08 06:15:00');
INSERT OR REPLACE INTO "DataQuest" ("ID","Name","StartType","StartName","StartRegionID","AcceptText","Description","SourceName","SourceText","StepType","StepText","StepItemTemplates","AdvanceText","TargetName","TargetText","CollectItemTemplate","MaxCount","MinLevel","MaxLevel","RewardMoney","RewardXP","RewardCLXP","RewardRP","RewardBP","OptionalRewardItemTemplates","FinalRewardItemTemplates","FinishText","QuestDependency","AllowedClasses","ClassType","LastTimeRowUpdated") VALUES (20388,'Guarding the Stone',0,'Sir Jerem',1,'Salisbury','My squire Graid guards a stone in [Salisbury] Plains and has not reported. Find him.','','Find Squire Graid at the large rock in Salisbury Plains and talk to him.|||','4|0|2|3','Find Squire Graid at the large rock in Salisbury Plains and talk to him.|Deal with the Ghostwalker''s Apprentice and the undead that accompany him.|Hand Squire Graid the apprentice''s pack.|Return to Sir Jerem in Prydwen Keep and give him the pack.','||cq_apprentice_s_pack|cq_apprentice_s_pack','|||','Squire Graid;1|Ghostwalker''s Apprentice;1|Squire Graid;1|Sir Jerem;1','|||','||cq_apprentice_s_pack|cq_apprentice_s_pack',1,12,20,'0|0|0|0','0|0|47040|47040',NULL,NULL,NULL,NULL,'cq_alb_apprentice_cloak','','','','DOL.GS.Quests.ClassicQuestStep','2026-10-08 06:15:00');
INSERT OR REPLACE INTO "DataQuest" ("ID","Name","StartType","StartName","StartRegionID","AcceptText","Description","SourceName","SourceText","StepType","StepText","StepItemTemplates","AdvanceText","TargetName","TargetText","CollectItemTemplate","MaxCount","MinLevel","MaxLevel","RewardMoney","RewardXP","RewardCLXP","RewardRP","RewardBP","OptionalRewardItemTemplates","FinalRewardItemTemplates","FinishText","QuestDependency","AllowedClasses","ClassType","LastTimeRowUpdated") VALUES (20389,'Widower Hunt',0,'Yver Tiu',100,'Muspelheim','There are oddities with the soot harvester spiders in [Muspelheim]. Please travel there and bring me their legs.','','Oh ho! You''ve returned! Glorious! Now, for the next task. You need to retrieve some more [parts] for me.|||||||||','0|10|2|2|0|2|2|2|0|5','Go to Muspelheim and slay a soot harvester.|Return the bundle of harvester legs to Yver in Haggerfel.|Take the note to Darrius in Fort Atla.|Take the spinnerets to Yver.|Travel to West Svealand and kill a blodfelag haxa.|Return the charm necklace to Yver.|Take Yver''s bundle to Averrius in Gna Faste near the guard tower.|Return the enchanted spider parts to Yver.|Go to Myrkwood and slay the Widower with Yric, Yver''s brother, just northwest of the Spindelhalla entrance.|Speak with Yric again.','cq_bundle_of_harvester_legs;50||cq_note_to_darrius|cq_silk_spinnerets||cq_charm_necklace|cq_bundle_of_spider_parts|cq_enchanted_spider_parts||','|||||||||','soot harvester;100|Yver Tiu;100|Darrius;100|Yver Tiu;100|blodfelag haxa;100|Yver Tiu;100|Averrius;100|Yver Tiu;100|Widower;100|Yric Tiu;100','|<Player> has truly outdone himself this time. I do now see the oddities of which he spoke about in his last letter. Now friend, there is [more to be done].||You continue to amaze me brave Kayje. Now, before this rite can be performed, you must take this bundle to Averrius, in Myrkwood. He is an enchanter and can open the magic within these pieces so I may properly focus on the corruption.||The package, thank you friend, thank you. Please wait while I perform this rite and cease the corruption of the Blodfelag once and for all.|Interesting, very interesting. Let me see what I can do with this. Please wait. I am finished. You may return these to Yver. He will now be able to do his rite. I hope he discovers who is behind all this.|While I though it was merely a legend, something to scare children with at night, I see now that I have been a fool. There is a spider of immense power called the [Widower] who roams the woods of Myrkwood.||So, Averrius, I should have known. You Arachite traitor! How dare you defile Midgard with your devious magic! We shall destroy you! You have done well young Kayje. I wish to reward you for your valiant attempts. I will make you a shield with the parts from his carapace. Let me imbue them with the power of Valhalla. This will only take a moment. Here you are. Use this shield well, and never forget the lessons we both learned here today.','|cq_bundle_of_harvester_legs|cq_note_to_darrius|cq_silk_spinnerets||cq_charm_necklace|cq_bundle_of_spider_parts|cq_enchanted_spider_parts||',1,21,50,'0|0|2400|0|0|0|0|0|0|30000','0|0|0|0|0|0|0|0|0|429000',NULL,NULL,NULL,NULL,'cq_mid_widower_shield','I fear Midgard is in peril friend. Quickly, travel to Myrkwood, he will meet you at the web covered tree near Spindelhalla. Quickly, you must hurry!','','','DOL.GS.Quests.ClassicQuestStep','2026-10-08 06:15:00');
