INSERT OR REPLACE INTO "DataQuest" ("ID","Name","StartType","StartName","StartRegionID","AcceptText","Description","SourceName","SourceText","StepType","StepText","StepItemTemplates","AdvanceText","TargetName","TargetText","CollectItemTemplate","MaxCount","MinLevel","MaxLevel","RewardMoney","RewardXP","RewardCLXP","RewardRP","RewardBP","OptionalRewardItemTemplates","FinalRewardItemTemplates","FinishText","QuestDependency","AllowedClasses","ClassType","LastTimeRowUpdated") VALUES (20836,'Tale of Cad Goddeau',0,'Benen',200,'trainer','Do you know about Cad Goddeau? Ask the Druid [trainer] at the tower over the bridge.','','Say [Cad Goddeau] to the Druid trainer at the tower over the bridge from Connla. (whisper: Cad Goddeau)|','6|5','Say [Cad Goddeau] to the Druid trainer at the tower over the bridge from Connla. (whisper: Cad Goddeau)|Return to your trainer.','|','Cad Goddeau|','Breeda;200|Benen;200','|','|',1,4,50,'0|0','0|232',NULL,NULL,NULL,NULL,'cq_hib_band_of_twigs','','','53','DOL.GS.Quests.ClassicQuestStep','2026-10-08 06:15:00');
