INSERT OR REPLACE INTO "DataQuest" ("ID","Name","StartType","StartName","StartRegionID","AcceptText","Description","SourceName","SourceText","StepType","StepText","StepItemTemplates","AdvanceText","TargetName","TargetText","CollectItemTemplate","MaxCount","MinLevel","MaxLevel","RewardMoney","RewardXP","RewardCLXP","RewardRP","RewardBP","OptionalRewardItemTemplates","FinalRewardItemTemplates","FinishText","QuestDependency","AllowedClasses","ClassType","LastTimeRowUpdated") VALUES (21423,'Traces of the Mad Changlings',0,'Tressa Gorrym''jiarg',200,'creature','Hmph, another noisy [creature]. And what is it you want?','','Well, <Player>, I see you are here. Unfortunately I cannot trade this necklace I have for you belt. The necklace would do nothing for a strong <Player> like you. Run along now!||Choose your reward: [Lusmorebane''s Jeweled Necklace], [Belt of Spryness].','0|2|9','From Caille head southeast across Moon Lake to the tall standing stones; the mad changelings are at the foot of the hills behind them. Kill Lusmorebane.|Bring the head back to Tressa.|Choose your reward: whisper Tressa Gorrym''jiarg the name of the item you want (Lusmorebane''s Jeweled Necklace, Belt of Spryness).','|cq_lusmorebane_s_head|','||','Lusmorebane;200|Tressa Gorrym''jiarg;200|Tressa Gorrym''jiarg;200','||','|cq_lusmorebane_s_head|',1,31,50,'0|0|10000','0|0|4161276',NULL,NULL,NULL,NULL,'cq_elven_gossamer','Make good use of this cloth Celt, I shall not be so generous in the future.','','','DOL.GS.Quests.ClassicQuestStep','2026-10-08 06:15:00');
